        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1].results || {};
            var finalSPI = last.spi || 0;
            var finalCPI = last.cpi || 0;
            var finalScope = last.scopeComplete || 0;
            var finalStake = last.stakeholderScore || 0;
            var finalScore = last.compositeScore || 0;
            var scores = history.map(function(r) { return r.results ? (r.results.compositeScore || 0) : 0; });
            var avgScore = Math.round(scores.reduce(function(s, v) { return s + v; }, 0) / scores.length);

            var T = function(k) { return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k; };
            var performance = T('rating_needs');
            if (finalScore >= 85) performance = T('rating_excellent');
            else if (finalScore >= 70) performance = T('rating_competent');
            else if (finalScore >= 55) performance = T('rating_developing');

            var insights = [];
            if (finalSPI < 0.90) insights.push(T('insight_schedule'));
            if (finalCPI < 0.90) insights.push(T('insight_cost'));
            if (finalScope < 90) insights.push(T('insight_scope'));
            if (finalStake < 65) insights.push(T('insight_stakeholder'));
            if (finalScore >= 85) insights.push(T('insight_strong'));
            if (insights.length === 0) insights.push(T('insight_solid'));

            return {
                finalScore: finalScore,
                averageScore: avgScore,
                finalSPI: finalSPI,
                finalCPI: finalCPI,
                scopeDelivered: finalScope + '%',
                stakeholderSatisfaction: finalStake,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.spi < 0.85) return window.mySimulation.t('hint_schedule_critical');
            if (results.cpi < 0.90) return window.mySimulation.t('hint_cost_overrun');
            if (results.stakeholderScore < 60) return window.mySimulation.t('hint_stakeholder_low');
            if (results.scopeComplete < 50 && state.currentPeriod >= 3) return window.mySimulation.t('hint_scope_behind');
            return null;
        }

